1	'use client';
2	
3	// AuthSessionProvider bridges Openfort identity with our app session.
4	//
5	// Design: Openfort owns auth (Google/Email OTP) and wallets. We own the app
6	// session (JWT + httpOnly refresh cookie), user profile, and the qualification
7	// gate. connectOnLogin: false means Openfort never auto-connects the wallet —
8	// we call create() explicitly at the right moment.
9	//
10	// Status machine:
11	//   idle → loading → needs_onboarding → loading → creating_wallet → authenticated
12	//                 ↘ creating_wallet → authenticated   (existing user)
13	//                 ↘ error                             (any failure)
14	//
15	// New-user path (registration):
16	//   Openfort auth → check backend (exists: false) → qualification questionnaire
17	//   → backend exchange with role/type → createWalletIfNeeded → authenticated
18	//
19	// Existing-user path (login):
20	//   Openfort auth → refresh cookie valid? → getBackendMe → createWalletIfNeeded
21	//                                        ↘ no cookie → check backend (exists: true)
22	//                                          → backend exchange → createWalletIfNeeded
23	//
24	// createWalletIfNeeded always calls Openfort's create() to load the iframe and
25	// establish the embedded-wallet connection. For new users create() provisions
26	// the wallet; for returning users it reconnects to the existing one. Skipping
27	// this step for returning users leaves the wallet in [Not connected] state
28	// because the embedded-wallet iframe is never loaded (connectOnLogin: false).
29	
30	import type { User } from '@openfort/openfort-js';
31	import { RecoveryMethod, useSignOut, useUI, useUser } from '@openfort/react';
32	import { useEthereumEmbeddedWallet } from '@openfort/react/ethereum';
33	import {
34	  checkOpenfortUser,
35	  deleteBackendAccount,
36	  exchangeOpenfortSession,
37	  getBackendMe,
38	  logoutBackendSession,
39	  refreshBackendSession,
40	  type BackendMeResponse,
41	} from '@/lib/backend-auth-client';
42	import {
43	  QualificationQuestionnaire,
44	  type QualificationSubmission,
45	} from './qualification-questionnaire';
46	import {
47	  createContext,
48	  useCallback,
49	  useContext,
50	  useEffect,
51	  useMemo,
52	  useRef,
53	  useState,
54	  type ReactNode,
55	} from 'react';
56	import { usePathname } from 'next/navigation';
57	import { reportError } from '@/lib/error-reporting';
58	
59	type AppSessionStatus =
60	  | 'idle'
61	  | 'loading'
62	  | 'needs_onboarding'
63	  | 'creating_wallet'
64	  | 'authenticated'
65	  | 'unauthenticated'
66	  | 'error';
67	
68	type ErrorCategory = 'recoverable' | 'fatal';
69	
70	interface AuthSessionContextValue {
71	  status: AppSessionStatus;
72	  backendAccessToken: string | null;
73	  backendUser: BackendMeResponse | null;
74	  openfortUser: User | null;
75	  isOpenfortLoading: boolean;
76	  isOpenfortAuthenticated: boolean;
77	  error: string | null;
78	  errorCategory: ErrorCategory | null;
79	  retry: () => void;
80	  deleteAccount: () => Promise<void>;
81	}
82	
83	const AuthSessionContext = createContext<AuthSessionContextValue | null>(null);
84	const ONBOARDING_STORAGE_KEY = 'infrafund:onboarding-draft';
85	
86	function getErrorMessage(error: unknown) {
87	  if (error instanceof Error && error.message) {
88	    return error.message;
89	  }
90	
91	  return 'Failed to initialize your session.';
92	}
93	
94	function getUserFacingErrorMessage(message: string) {
95	  if (/failed to establish iFrame connection/i.test(message)) {
96	    return "We couldn't connect to the wallet service. Please check your connection and try again.";
97	  }
98	
99	  if (/not logged in|session/i.test(message)) {
100	    return 'Your session expired. Please sign in again.';
101	  }
102	
103	  if (/failed to fetch|networkerror/i.test(message)) {
104	    return 'We hit a network issue. Please try again.';
105	  }
106	
107	  return 'Something went wrong. Please try again.';
108	}
109	
110	function classifyError(message: string): ErrorCategory {
111	  if (
112	    /failed to fetch|networkerror|failed to establish iframe|timeout|temporarily|try again/i.test(
113	      message
114	    )
115	  ) {
116	    return 'recoverable';
117	  }
118	
119	  return 'fatal';
120	}
121	
122	function clearOnboardingDraft() {
123	  if (typeof window !== 'undefined') {
124	    window.sessionStorage.removeItem(ONBOARDING_STORAGE_KEY);
125	  }
126	}
127	
128	export function AuthSessionProvider({ children }: { children: ReactNode }) {
129	  const { user, isLoading, isAuthenticated, getAccessToken } = useUser();
130	  const { signOut } = useSignOut();
131	  const { close: closeOpenfortModal } = useUI();
132	  const { create, wallets } = useEthereumEmbeddedWallet();
133	  const openfortUserId = user?.id ?? null;
134	  const [status, setStatus] = useState<AppSessionStatus>('idle');
135	  const [backendAccessToken, setBackendAccessToken] = useState<string | null>(
136	    null
137	  );
138	  const [backendUser, setBackendUser] = useState<BackendMeResponse | null>(
139	    null
140	  );
141	  const [error, setError] = useState<string | null>(null);
142	  const [errorCategory, setErrorCategory] = useState<ErrorCategory | null>(
143	    null
144	  );
145	  const [retryCount, setRetryCount] = useState(0);
146	  const pathname = usePathname();
147	  const [pendingOnboardingAccessToken, setPendingOnboardingAccessToken] =
148	    useState<string | null>(null);
149	  const [pendingWalletCreation, setPendingWalletCreation] = useState<{
150	    accessToken: string;
151	    user: BackendMeResponse;
152	  } | null>(null);
153	  const previousAuthState = useRef(false);
154	  // Deduplication key: we only run one bootstrap per (userId, retryCount) pair.
155	  // This prevents the useEffect from re-triggering bootstrap when callbacks are
156	  // recreated due to dependency changes mid-flow.
157	  const bootstrapAttemptKeyRef = useRef<string | null>(null);
158	
159	  const clearSession = useCallback(() => {
160	    setBackendAccessToken(null);
161	    setBackendUser(null);
162	    setPendingOnboardingAccessToken(null);
163	    setPendingWalletCreation(null);
164	    setError(null);
165	    setErrorCategory(null);
166	    bootstrapAttemptKeyRef.current = null;
167	    clearOnboardingDraft();
168	  }, []);
169	
170	  const commitUserFacingError = useCallback((raw: string) => {
171	    const userMessage = getUserFacingErrorMessage(raw);
172	    setError(userMessage);
173	    setErrorCategory(classifyError(raw));
174	    return userMessage;
175	  }, []);
176	
177	  const baseReportExtras = useCallback(
178	    () => ({
179	      route: pathname ?? null,
180	      retryCount,
181	      openfortUserId: openfortUserId ? openfortUserId.slice(-6) : null,
182	    }),
183	    [openfortUserId, pathname, retryCount]
184	  );
185	
186	  // Terminal success state: app session is fully established and the wallet
187	  // iframe is connected. Closes any Openfort modal still visible and resets
188	  // all transient state accumulated during the auth/onboarding flow.
189	  const finalizeAuthenticatedSession = useCallback(
190	    (accessToken: string, currentUser: BackendMeResponse) => {
191	      closeOpenfortModal();
192	      setBackendAccessToken(accessToken);
193	      setBackendUser(currentUser);
194	      setPendingOnboardingAccessToken(null);
195	      setPendingWalletCreation(null);
196	      setError(null);
197	      setErrorCategory(null);
198	      clearOnboardingDraft();
199	      setStatus('authenticated');
200	    },
201	    [closeOpenfortModal]
202	  );
203	
204	  // Loads the Openfort embedded-wallet iframe and connects/creates the wallet,
205	  // then transitions to authenticated.
206	  //
207	  // Context when called: the backend session is already established (accessToken
208	  // and currentUser are valid). The Openfort SDK is authenticated. The only
209	  // remaining step is to load the hidden iframe so the wallet is usable.
210	  //
211	  // Why always call create(): connectOnLogin: false means the SDK never loads
212	  // the iframe automatically. create() is the correct call for both paths:
213	  //   - New user:      provisions the wallet and connects it via the iframe.
214	  //   - Existing user: reconnects to the existing wallet via the iframe.
215	  //                    The SDK's wallets[] array may already contain the wallet
216	  //                    (fetched from the Openfort API), but that does not mean
217	  //                    the iframe is loaded — without it the wallet is [Not
218	  //                    connected] and cannot sign transactions. Skipping create()
219	  //                    when wallets.length > 0 was the original bug causing
220	  //                    returning users to see [Not connected] on every login.
221	  const createWalletIfNeeded = useCallback(
222	    async (accessToken: string, currentUser: BackendMeResponse) => {
223	      setBackendAccessToken(accessToken);
224	      setBackendUser(currentUser);
225	      setPendingWalletCreation({ accessToken, user: currentUser });
226	      setStatus('creating_wallet');
227	
228	      try {
229	        await create({
230	          recoveryMethod: RecoveryMethod.AUTOMATIC,
231	        });
232	        finalizeAuthenticatedSession(accessToken, currentUser);
233	      } catch (walletError) {
234	        const rawMessage = getErrorMessage(walletError);
235	        reportError(walletError, {
236	          area: 'wallet',
237	          tags: { stage: 'create' },
238	          extra: {
239	            ...baseReportExtras(),
240	            hasExistingWallet: wallets.length > 0,
241	          },
242	        });
243	        commitUserFacingError(rawMessage);
244	        setStatus('error');
245	      }
246	    },
247	    [
248	      baseReportExtras,
249	      commitUserFacingError,
250	      create,
251	      finalizeAuthenticatedSession,
252	      wallets.length,
253	    ]
254	  );
255	
256	  // Runs once per Openfort user identity (keyed on openfortUserId + retryCount).
257	  // Determines which path the user takes and drives them to createWalletIfNeeded.
258	  //
259	  // Priority order:
260	  //   1. Valid refresh cookie → restore the app session directly, skip Openfort
261	  //      token exchange (faster; avoids an extra round-trip to Openfort API).
262	  //   2. No refresh cookie, existing backend user → exchange Openfort token for
263	  //      app session.
264	  //   3. No backend user → show qualification questionnaire; wallet creation is
265	  //      deferred until completeOnboarding() succeeds.
266	  const bootstrapSession = useCallback(async () => {
267	    if (!openfortUserId) {
268	      clearSession();
269	      setStatus('unauthenticated');
270	      return;
271	    }
272	
273	    setStatus('loading');
274	    setError(null);
275	
276	    try {
277	      // Path 1: try to restore an existing app session via the refresh cookie.
278	      // This is the fast path for page reloads and returning sessions.
279	      const refreshedSession = await refreshBackendSession().catch(() => null);
280	
281	      if (refreshedSession) {
282	        try {
283	          const me = await getBackendMe(refreshedSession.access_token);
284	          // Route through createWalletIfNeeded (not finalizeAuthenticatedSession
285	          // directly) so the embedded-wallet iframe is loaded and the wallet
286	          // becomes usable for signing — even on session restore.
287	          await createWalletIfNeeded(refreshedSession.access_token, me);
288	          return;
289	        } catch {
290	          // Refresh token was valid but user is inaccessible (e.g. soft-deleted).
291	          // Clear the stale cookie and fall through to Openfort re-auth.
292	          await logoutBackendSession().catch(() => undefined);
293	        }
294	      }
295	
296	      // Paths 2 & 3: no valid refresh cookie; re-authenticate via Openfort token.
297	      const openfortAccessToken = await getAccessToken();
298	
299	      if (!openfortAccessToken) {
300	        throw new Error('Openfort access token is unavailable.');
301	      }
302	
303	      const checkResponse = await checkOpenfortUser(openfortAccessToken);
304	
305	      if (!checkResponse.exists) {
306	        // Path 3: new user — hold the Openfort token and show the qualification
307	        // questionnaire. Wallet creation is deferred to completeOnboarding().
308	        closeOpenfortModal();
309	        setPendingOnboardingAccessToken(openfortAccessToken);
310	        setStatus('needs_onboarding');
311	        return;
312	      }
313	
314	      // Path 2: existing user — exchange the Openfort token for an app session.
315	      const loginResponse = await exchangeOpenfortSession(openfortAccessToken);
316	      const me = await getBackendMe(loginResponse.access_token);
317	
318	      await createWalletIfNeeded(loginResponse.access_token, me);
319	    } catch (sessionError) {
320	      reportError(sessionError, {
321	        area: 'auth',
322	        tags: { stage: 'bootstrap' },
323	        extra: baseReportExtras(),
324	      });
325	      setBackendAccessToken(null);
326	      setBackendUser(null);
327	      setPendingOnboardingAccessToken(null);
328	      setPendingWalletCreation(null);
329	      commitUserFacingError(getErrorMessage(sessionError));
330	      setStatus('error');
331	    }
332	  }, [
333	    baseReportExtras,
334	    clearSession,
335	    closeOpenfortModal,
336	    commitUserFacingError,
337	    createWalletIfNeeded,
338	    getAccessToken,
339	    openfortUserId,
340	  ]);
341	
342	  // Called when the user submits the qualification questionnaire.
343	  // Context: status === 'needs_onboarding', pendingOnboardingAccessToken is set.
344	  // The Openfort token is still valid; no app session exists yet.
345	  const completeOnboarding = useCallback(
346	    async ({ role, type, organizationName }: QualificationSubmission) => {
347	      if (!pendingOnboardingAccessToken) {
348	        setError('Openfort access token is unavailable.');
349	        setStatus('error');
350	        return;
351	      }
352	
353	      setStatus('loading');
354	      setError(null);
355	
356	      try {
357	        const loginResponse = await exchangeOpenfortSession(
358	          pendingOnboardingAccessToken,
359	          {
360	            role,
361	            type,
362	            organization_name:
363	              type === 'organization' ? organizationName?.trim() : undefined,
364	          }
365	        );
366	        const me = await getBackendMe(loginResponse.access_token);
367	
368	        await createWalletIfNeeded(loginResponse.access_token, me);
369	      } catch (sessionError) {
370	        reportError(sessionError, {
371	          area: 'auth',
372	          tags: { stage: 'onboarding' },
373	          extra: baseReportExtras(),
374	        });
375	        commitUserFacingError(getErrorMessage(sessionError));
376	        setStatus('needs_onboarding');
377	      }
378	    },
379	    [
380	      baseReportExtras,
381	      commitUserFacingError,
382	      createWalletIfNeeded,
383	      pendingOnboardingAccessToken,
384	    ]
385	  );
386	
387	  const abandonOnboarding = useCallback(async () => {
388	    clearSession();
389	    setStatus('loading');
390	
391	    await Promise.allSettled([
392	      logoutBackendSession(),
393	      signOut().catch(() => undefined),
394	    ]);
395	
396	    clearSession();
397	    setStatus('unauthenticated');
398	  }, [clearSession, signOut]);
399	
400	  const deleteAccount = useCallback(async () => {
401	    setStatus('loading');
402	    setError(null);
403	
404	    try {
405	      if (backendAccessToken) {
406	        await deleteBackendAccount(backendAccessToken);
407	      }
408	    } catch (deleteError) {
409	      reportError(deleteError, {
410	        area: 'auth',
411	        tags: { stage: 'delete-account' },
412	        extra: baseReportExtras(),
413	      });
414	      commitUserFacingError(getErrorMessage(deleteError));
415	      setStatus('authenticated');
416	      return;
417	    }
418	
419	    await Promise.allSettled([
420	      logoutBackendSession().catch(() => undefined),
421	      signOut().catch(() => undefined),
422	    ]);
423	
424	    clearSession();
425	    setStatus('unauthenticated');
426	  }, [
427	    backendAccessToken,
428	    baseReportExtras,
429	    clearSession,
430	    commitUserFacingError,
431	    signOut,
432	  ]);
433	
434	  const retry = useCallback(() => {
435	    if (pendingWalletCreation) {
436	      void createWalletIfNeeded(
437	        pendingWalletCreation.accessToken,
438	        pendingWalletCreation.user
439	      );
440	      return;
441	    }
442	
443	    setRetryCount((count) => count + 1);
444	  }, [createWalletIfNeeded, pendingWalletCreation]);
445	
446	  // Primary driver: react to Openfort auth state changes.
447	  // bootstrapAttemptKey deduplicate calls so we run bootstrap exactly once
448	  // per (user, retryCount) pair, even when the effect re-fires because a
449	  // callback was recreated due to dependency changes mid-flow.
450	  useEffect(() => {
451	    if (isLoading) {
452	      setStatus((currentStatus) =>
453	        currentStatus === 'authenticated' ||
454	        currentStatus === 'needs_onboarding'
455	          ? currentStatus
456	          : 'loading'
457	      );
458	      return;
459	    }
460	
461	    if (!isAuthenticated || !openfortUserId) {
462	      clearSession();
463	      setStatus('unauthenticated');
464	      return;
465	    }
466	
467	    const bootstrapAttemptKey = `${openfortUserId}:${retryCount}`;
468	
469	    if (bootstrapAttemptKeyRef.current === bootstrapAttemptKey) {
470	      return;
471	    }
472	
473	    bootstrapAttemptKeyRef.current = bootstrapAttemptKey;
474	
475	    void bootstrapSession();
476	  }, [
477	    bootstrapSession,
478	    clearSession,
479	    isAuthenticated,
480	    isLoading,
481	    openfortUserId,
482	    retryCount,
483	  ]);
484	
485	  // Secondary driver: detect explicit sign-out. Openfort's own sign-out does
486	  // not call our logout endpoint, so we must revoke the app session cookie here.
487	  useEffect(() => {
488	    const signedOut =
489	      previousAuthState.current && !isLoading && !isAuthenticated;
490	
491	    previousAuthState.current = isAuthenticated;
492	
493	    if (!signedOut) {
494	      return;
495	    }
496	
497	    clearSession();
498	    setStatus('unauthenticated');
499	    void logoutBackendSession().catch(() => undefined);
500	  }, [clearSession, isAuthenticated, isLoading]);
501	
502	  const value = useMemo<AuthSessionContextValue>(
503	    () => ({
504	      status,
505	      backendAccessToken,
506	      backendUser,
507	      openfortUser: user,
508	      isOpenfortLoading: isLoading,
509	      isOpenfortAuthenticated: isAuthenticated,
510	      error,
511	      errorCategory,
512	      retry,
513	      deleteAccount,
514	    }),
515	    [
516	      status,
517	      backendAccessToken,
518	      backendUser,
519	      user,
520	      isLoading,
521	      isAuthenticated,
522	      error,
523	      errorCategory,
524	      retry,
525	      deleteAccount,
526	    ]
527	  );
528	
529	  return (
530	    <AuthSessionContext.Provider value={value}>
531	      {children}
532	      <QualificationQuestionnaire
533	        isOpen={status === 'needs_onboarding'}
534	        openfortUser={user}
535	        submitError={error}
536	        isSubmitting={status === 'loading'}
537	        onClose={() => {
538	          void abandonOnboarding();
539	        }}
540	        onSubmit={completeOnboarding}
541	        onDisqualifiedSuccess={abandonOnboarding}
542	      />
543	    </AuthSessionContext.Provider>
544	  );
545	}
546	
547	export function useAuthSession() {
548	  const context = useContext(AuthSessionContext);
549	
550	  if (!context) {
551	    throw new Error(
552	      'useAuthSession must be used within an AuthSessionProvider.'
553	    );
554	  }
555	
556	  return context;
557	}
